export function clamp(value, min, max) {
  if (!Number.isFinite(value)) {
    throw new TypeError("value");
  }
  if (min > max) {
    throw new RangeError("range");
  }
  if (value < min) {
    return min;
  }
  if (value > max) {
    return max;
  }
  return value;
}

export function classify(event) {
  if (event === null || typeof event !== "object") {
    throw new TypeError("event");
  }
  const attempt = event.attempt ?? 0;
  if (!Number.isInteger(attempt) || attempt < 0) {
    throw new RangeError("attempt");
  }
  switch (event.kind) {
    case "start": {
      return { state: "running", terminal: false, retryable: false };
    }
    case "success": {
      return { state: "done", terminal: true, retryable: false };
    }
    case "retry": {
      return { state: "waiting", terminal: false, retryable: attempt < 3 };
    }
    case "cancel": {
      return { state: "cancelled", terminal: true, retryable: false };
    }
    case "timeout": {
      return { state: "failed", terminal: true, retryable: attempt < 3 };
    }
    case "error": {
      return { state: "failed", terminal: true, retryable: false };
    }
    case "pause": {
      return { state: "paused", terminal: false, retryable: false };
    }
    default: {
      return { state: "unknown", terminal: false, retryable: false };
    }
  }
}

