export function formatTotal(items, rate, currency) { return ""; }
export const untouched = "keep";

cells.expectedSource:
export function formatTotal(items, rate, currency) {
  if (!Array.isArray(items)) {
    throw new TypeError("items");
  }
  let cents = 0;
  for (const value of items) {
    cents += toCents(value);
  }
  const taxed = applyTax(cents, rate);
  return formatMoney({ cents: taxed, currency });
}

helpers.helper.mjs:
export function toCents(value) {
  if (typeof value !== "number" || !Number.isFinite(value)) { throw new TypeError("amount"); }
  return Math.round(value * 100);
}
export function applyTax(cents, rate) {
  if (!Number.isFinite(rate) || rate < 0) { throw new RangeError("rate"); }
  return Math.round(cents * (1 + rate));
}
export function formatMoney({ cents, currency }) {
  if (!["USD", "EUR"].includes(currency)) { throw new RangeError("currency"); }
  return `${currency} ${(cents / 100).toFixed(2)}`;
}
export function parseCents(text) {
  if (typeof text !== "string" || !/^-?\d+(?:\.\d{1,2})?$/.test(text)) { return null; }
  return Math.round(Number(text) * 100);
}

