export function summarize(rows, currency) {
  if (!Array.isArray(rows)) {
    throw new TypeError("rows");
  }
  const groups = new Map();
  let accepted = 0;
  let rejected = 0;
  let total = 0;
  for (const row of rows) {
    if (row === null || typeof row !== "object" || typeof row.account !== "string" || row.account.trim() === "") {
      rejected++;
      continue;
    }
    const cents = parseCents(row.amount);
    if (cents === null) {
      rejected++;
      continue;
    }
    const account = row.account.trim();
    groups.set(account, (groups.get(account) ?? 0) + cents);
    total += cents;
    accepted++;
  }
  const accounts = [...groups.keys()].sort().map(account => ({
    account,
    balance: formatMoney({ cents: groups.get(account), currency }),
  }));
  return {
    accepted,
    rejected,
    total: formatMoney({ cents: total, currency }),
    accounts,
  };
}

